import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    nums = [int(x) for x in data[1:1+n]]
    res = 0
    for num in nums:
        res ^= num
    print(res)

if __name__ == '__main__':
    solve()

