#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int res = 0;
    for (int i = 0; i < n; i++) {
        int val;
        scanf("%d", &val);
        res ^= val;
    }
    printf("%d\n", res);
    return 0;
}
